{
  "name": "NI-DAQmx 系统管理组件",
  "name_en": "NI-DAQmx System Manager",
  "manufacturer": "National Instruments (NI)",
  "description": "这是一个非物理的软件系统管理组件，用于表示和管理 NI-DAQmx 数据采集系统。它用于访问本地或远程 DAQmx 系统、枚举设备与已保存任务/通道/标度，并执行与硬件配置相关的系统级操作，如端子路由、上电默认状态设置以及 cDAQ 同步连接配置。",
  "description_en": "This is a non-physical software system management component that represents and manages an NI-DAQmx data acquisition system. It is used to access local or remote DAQmx systems, enumerate devices and persisted tasks/channels/scales, and perform system-level hardware configuration operations such as terminal routing, power-up state configuration, and cDAQ synchronization setup.",
  "tag_hints": [
    "NI-DAQmx",
    "DAQ system management",
    "device enumeration",
    "terminal routing",
    "power-up state configuration",
    "cDAQ synchronization",
    "persisted tasks and channels"
  ],
  "actions": [
    {
      "action_name": "auto-local",
      "description": "获取本地 DAQmx 系统对象。",
      "description_en": "Get the local DAQmx system object."
    },
    {
      "action_name": "auto-remote",
      "description": "连接并获取远程 DAQmx 系统对象。",
      "description_en": "Connect to and get a remote DAQmx system object."
    },
    {
      "action_name": "auto-devices",
      "description": "获取该 DAQmx 系统中的设备集合。",
      "description_en": "Get the collection of devices in this DAQmx system."
    },
    {
      "action_name": "auto-driver_version",
      "description": "获取已安装 NI-DAQmx 驱动的版本信息。",
      "description_en": "Get the installed NI-DAQmx driver version information."
    },
    {
      "action_name": "auto-global_channels",
      "description": "获取系统中已保存的全局通道集合。",
      "description_en": "Get the collection of persisted global channels in the system."
    },
    {
      "action_name": "auto-scales",
      "description": "获取系统中已保存的自定义标度集合。",
      "description_en": "Get the collection of persisted custom scales in the system."
    },
    {
      "action_name": "auto-tasks",
      "description": "获取系统中已保存的任务集合。",
      "description_en": "Get the collection of persisted tasks in the system."
    },
    {
      "action_name": "auto-connect_terms",
      "description": "在源端子和目标端子之间创建信号路由。",
      "description_en": "Create a signal route between a source terminal and a destination terminal."
    },
    {
      "action_name": "auto-disconnect_terms",
      "description": "移除已创建的端子信号路由。",
      "description_en": "Remove a previously created terminal signal route."
    },
    {
      "action_name": "auto-tristate_output_term",
      "description": "将输出端子设置为高阻态。",
      "description_en": "Set an output terminal to a high-impedance state."
    },
    {
      "action_name": "auto-set_digital_power_up_states",
      "description": "设置指定设备数字物理通道的上电默认状态。",
      "description_en": "Set the power-up default states for digital physical channels on a specified device."
    },
    {
      "action_name": "auto-get_digital_power_up_states",
      "description": "获取指定设备数字物理线路的上电默认状态。",
      "description_en": "Get the power-up default states for digital physical lines on a specified device."
    },
    {
      "action_name": "auto-set_digital_pull_up_pull_down_states",
      "description": "设置数字线路在三态逻辑下的上拉/下拉电阻状态。",
      "description_en": "Set the pull-up or pull-down resistor states for digital lines in tristate logic."
    },
    {
      "action_name": "auto-get_digital_pull_up_pull_down_states",
      "description": "获取数字线路在三态逻辑下的上拉/下拉电阻状态。",
      "description_en": "Get the pull-up or pull-down resistor states for digital lines in tristate logic."
    },
    {
      "action_name": "auto-set_analog_power_up_states",
      "description": "设置指定设备模拟物理通道的上电默认状态。",
      "description_en": "Set the power-up default states for analog physical channels on a specified device."
    },
    {
      "action_name": "auto-set_analog_power_up_states_with_output_type",
      "description": "按输出类型设置模拟物理通道的上电默认状态。",
      "description_en": "Set the power-up default states for analog physical channels with output type information."
    },
    {
      "action_name": "auto-get_analog_power_up_states",
      "description": "获取指定设备模拟物理通道的上电默认状态。",
      "description_en": "Get the power-up default states for analog physical channels on a specified device."
    },
    {
      "action_name": "auto-get_analog_power_up_states_with_output_type",
      "description": "按物理通道获取模拟通道的上电默认状态及输出类型信息。",
      "description_en": "Get the power-up default states and output type information for analog channels by physical channel."
    },
    {
      "action_name": "auto-set_digital_logic_family_power_up_state",
      "description": "设置设备上电时使用的数字逻辑电平族。",
      "description_en": "Set the digital logic family used by a device at power-up."
    },
    {
      "action_name": "auto-get_digital_logic_family_power_up_state",
      "description": "获取设备的数字逻辑电平族设置。",
      "description_en": "Get the digital logic family setting for a device."
    },
    {
      "action_name": "auto-auto_configure_cdaq_sync_connections",
      "description": "自动检测并配置设备之间的 cDAQ 同步连接。",
      "description_en": "Automatically detect and configure cDAQ synchronization connections between devices."
    },
    {
      "action_name": "auto-are_configured_cdaq_sync_ports_disconnected",
      "description": "检查已配置的 cDAQ 同步端口是否断开。",
      "description_en": "Check whether configured cDAQ synchronization ports are disconnected."
    },
    {
      "action_name": "auto-add_cdaq_sync_connection",
      "description": "添加一条 cDAQ 同步连接配置。",
      "description_en": "Add a cDAQ synchronization connection configuration."
    },
    {
      "action_name": "auto-remove_cdaq_sync_connection",
      "description": "移除一条 cDAQ 同步连接配置。",
      "description_en": "Remove a cDAQ synchronization connection configuration."
    }
  ]
}

